def create_page_settings_and_refresh_owner_badge(apps, schema_editor):
    SiteConfiguration = apps.get_model("blog", "SiteConfiguration")
    StandalonePage = apps.get_model("blog", "StandalonePage")
    BadgeTranslation = apps.get_model("blog", "CommentBadgeTranslation")

    for config in SiteConfiguration.objects.all().iterator():
        defaults = (
            ("archives", "Archives", "archives", True),
            ("categories", "Categories", "categories", True),
            ("tags", "Tags", "tags", True),
            ("friends", "Friends", "friends", config.friends_enabled),
            ("bookmarks", "Bookmarks", "bookmarks", config.bookmarks_enabled),
            ("essays", "Essays", "essays", config.essays_enabled),
            ("masonry", "Masonry", "masonry", config.masonry_enabled),
        )
        StandalonePage.objects.bulk_create(
            [
                StandalonePage(
                    config=config,
                    page_type=page_type,
                    title=title,
                    slug=slug,
                    enabled=enabled,
                    friends_columns=config.friends_page_columns,
                    tags_style=config.tags_page_style,
                )
                for page_type, title, slug, enabled in defaults
            ]
        )

    replacements = {
        "es": ("Autor", "Bloguero"),
        "fr": ("Auteur", "Blogueur"),
        "ja": ("ブログ管理者", "ブロガー"),
        "zh-hk": ("博主", "部落客"),
        "zh-tw": ("站長", "部落客"),
    }
    for language_code, (old_name, new_name) in replacements.items():
        BadgeTranslation.objects.filter(
            badge__is_owner_badge=True,
            language_code=language_code,
            name=old_name,
        ).update(name=new_name)


